.liquid-panel{background: linear-gradient(rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)); backdrop-filter: blur(60px) saturate(1.4); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.5) 0px 30px 120px, rgba(97, 218, 251, 0.06) 0px 0px 80px;}
.dew{position: relative; overflow: hidden; background: linear-gradient(rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.05)); backdrop-filter: blur(30px) saturate(1.8); border: 1px solid rgba(255, 255, 255, 0.12); box-shadow: rgba(255, 255, 255, 0.18) 0px 1px 0px inset, rgba(97, 218, 251, 0.18) 0px 0px 40px; transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.6s;}
.dew:hover{transform: translateY(-5px) scale(1.02); box-shadow: rgba(255, 255, 255, 0.2) 0px 1px 0px inset, rgba(97, 218, 251, 0.28) 0px 0px 60px;}
.wind-sway{display: inline-block; transform-origin: center bottom; animation: 8s ease-in-out 0s infinite normal none running wind;}
.organic-shell{position: relative; overflow: hidden; isolation: isolate; border-radius: 44% 56% 58% 42% / 42% 36% 64% 58%; mask-image: radial-gradient(circle, black 40%, transparent 74%); filter: drop-shadow(rgba(97, 218, 251, 0.18) 0px 0px 80px);}
.organic-shell::before{content: ""; position: absolute; inset: -10%; background: radial-gradient(circle, rgba(97, 218, 251, 0.2), transparent 60%); filter: blur(50px); z-index: 2; pointer-events: none;}
.bloom{opacity: 0; transform: translateY(60px) scale(0.96); transition: opacity 1.2s cubic-bezier(0.16, 1, 0.3, 1), transform 1.2s cubic-bezier(0.16, 1, 0.3, 1);}
.bloom.active{opacity: 1; transform: translateY(0px) scale(1);}
.pulse-react{animation: 4s ease-in-out 0s infinite normal none running pulseReact;}
.light-river{position: absolute; inset: auto 0px; height: 1px; background: linear-gradient(90deg, transparent, rgba(97, 218, 251, 0.35), rgba(140, 255, 180, 0.4), transparent); filter: blur(0.4px);}
.float-core{animation: 9s ease-in-out 0s infinite normal none running drift;}
@supports (animation-timeline: view()){.scroll-grow{animation-duration: auto; animation-timing-function: linear; animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: both; animation-play-state: running; animation-name: grow; animation-timeline: view(); animation-range: entry 10% cover 65%;}}
